import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"국가 08 노량진남관상회","description":"","frontmatter":{},"headers":[],"relativePath":"world/Cast-State-08.md","filePath":"world/Cast-State-08.md"}'),t={name:"world/Cast-State-08.md"};function h(o,l,u,n,d,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="국가-08-노량진남관상회" tabindex="-1">국가 08 노량진남관상회 <a class="header-anchor" href="#국가-08-노량진남관상회" aria-label="Permalink to &quot;국가 08 노량진남관상회&quot;">​</a></h1><p>냉동상인 대표 오해린 곁의 경매·호송·얼음 실세다.</p><h3 id="인물-조민재" tabindex="-1">인물 조민재 <a class="header-anchor" href="#인물-조민재" aria-label="Permalink to &quot;인물 조민재&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 냉동 상인</li><li>성격: 손실을 숨기는 동료를 참지 못하고, 숫자보다 냄새로 창고 상태를 먼저 읽는다. 흥정에서는 웃지만 온도계가 흔들리면 표정이 굳는다.</li><li>개인 야망: 얼음 벽돌과 단기 식량 재고를 오해린의 결제권 담보로 묶어 가락의 가격 주도권을 남관이 가져온다.</li><li>공포: 전력이 하루만 끊겨도 냉동창고의 신용이 녹아내리는 것.</li><li>통치 방식: 재고 온도와 중량을 정오에 공개하고, 허위 재고가 나오면 해당 칸의 경매 자격을 박탈한다.</li><li>핵심 관계: 오해린의 지휘 아래 한재목과 전력·물 계약을 실무로 돌린다. 송이든에게 냉동 화물을 맡기고, 남윤경과 시세 발표 시각을 다툰다.</li><li>촉발 사건: 정전으로 남관 삼호 창고의 온도가 위험선까지 오르자 상인들이 재고를 밤사이에 옮기기 시작했다.</li><li>플레이어 개입: 발전 부품을 구해 냉동을 살리거나, 녹은 재고를 가득 찬 것처럼 적은 장부를 폭로할 수 있다.</li></ul><h3 id="인물-윤서하" tabindex="-1">인물 윤서하 <a class="header-anchor" href="#인물-윤서하" aria-label="Permalink to &quot;인물 윤서하&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 경매사</li><li>성격: 목소리가 맑고 잔인할 만큼 공정하다. 입찰자가 눈짓을 교환하면 즉시 그 품목을 다음 회로 미룬다.</li><li>개인 야망: 물·전력·식량 계약을 같은 경매판에서 교환하게 만들어 오해린의 공통 결제권을 시장 규칙으로 굳힌다.</li><li>공포: 강국이 비공개 직거래로 경매판을 빈 의자로 만드는 것.</li><li>통치 방식: 시작가와 낙찰가를 벽에 쓰고, 호송권만은 별도 봉투 경매로 돌린다.</li><li>핵심 관계: 오해린에게 호송권 비공개 경매를 위임받았고 남윤경과 가격 주도권을 경쟁한다. 신태산의 호송 입찰을 자주 낙찰시킨다.</li><li>촉발 사건: 흉작 소문만으로 가락 시세가 뛰자 남관 경매판에도 빈 상자가 고가로 나가기 시작했다.</li><li>플레이어 개입: 실제 재고를 경매 전에 공개하거나, 특정 후계자에게 군량 입찰을 몰아줄 수 있다.</li></ul><h3 id="인물-신태산" tabindex="-1">인물 신태산 <a class="header-anchor" href="#인물-신태산" aria-label="Permalink to &quot;인물 신태산&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 호송 반장</li><li>성격: 과묵하고 신의가 강하다. 호송 중에 화물을 열어본 대원은 그날로 자경대에서 뺀다.</li><li>개인 야망: 남관 호송선단을 약소국 공동호송의 실무 뼈대로 키워 강국의 보호비를 시장 자경으로 대체한다.</li><li>공포: 호송 열차가 군수품을 실어 중립시장 정통성이 하루 만에 무너지는 것.</li><li>통치 방식: 경로와 무장은 출발 직전에만 알리고, 도착 중량이 출발과 다르면 전 대원 배급을 깎는다.</li><li>핵심 관계: 오해린과 호송 계약을 맺고 송이든의 환적 창에서 인계한다. 장세화의 공동호송 초안을 현장 기준으로 검토 중이다.</li><li>촉발 사건: 한 호송칸에서 암사제 봉인 상자가 나와 시장 자경대가 선단 출항을 막았다.</li><li>플레이어 개입: 밀수 상자의 출처를 밝히거나, 호송을 강행해 남관의 중립을 시험할 수 있다.</li></ul><h3 id="인물-서나연" tabindex="-1">인물 서나연 <a class="header-anchor" href="#인물-서나연" aria-label="Permalink to &quot;인물 서나연&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 얼음 상인</li><li>성격: 꼼꼼하고 인색해 보이지만 병든 아이에게는 얼음을 먼저 푼다. 온도보다 신용이 먼저 녹는다고 말한다.</li><li>개인 야망: 얼음 벽돌을 결제 단위로 표준화해 전력이 흔들려도 남관 시세가 하루를 버티게 한다.</li><li>공포: 한강 취수와 제빙 전력이 동시에 끊겨 얼음 원장이 종이쪼가리가 되는 것.</li><li>통치 방식: 벽돌 무게와 제작 시각을 각인하고, 녹은 얼음으로 중량을 맞춘 상인을 시장에서 내보낸다.</li><li>핵심 관계: 오해린의 담보 창고를 채우고 조민재와 온도 기록을 공유한다. 윤지율에게 의무실 얼음을 우선 배정한다.</li><li>촉발 사건: 정전 첫날 제빙기가 멈추자 상인들이 녹은 물을 다시 얼렸다며 중량을 속이기 시작했다.</li><li>플레이어 개입: 수동 제빙 도구를 들여오거나, 가짜 중량 벽돌을 경매 전에 깨 보일 수 있다.</li></ul><h3 id="인물-오도윤" tabindex="-1">인물 오도윤 <a class="header-anchor" href="#인물-오도윤" aria-label="Permalink to &quot;인물 오도윤&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 운송선주 평의</li><li>성격: 표정을 잘 숨기고 표를 물건처럼 옮긴다. 손실을 나중으로 미루는 사람을 가장 경멸한다.</li><li>개인 야망: 상회정의 표를 선주 쪽으로 모아 오해린의 결제권 발행을 선박·호송 지분으로 묶는다.</li><li>공포: 외부 어획이 끊긴 뒤에도 허위 재고로 표를 산 선주들이 한꺼번에 파산하는 것.</li><li>통치 방식: 출항 전에 연료와 얼음 잔량을 공개하고, 미상환 표가 쌓인 선주의 부두 사용을 정지한다.</li><li>핵심 관계: 오해린과 상회정 표를 거래하고 한재목의 수상 운송 통행세를 꺼린다. 신태산의 호송 반을 선단에 태운다.</li><li>촉발 사건: 전력 단절과 함께 부두 잔여 어획이 하루치로 줄자 선주들이 결제권 발행을 앞당기라고 압박했다.</li><li>플레이어 개입: 선주 표를 모아 발행을 통과시키거나, 허위 재고로 산 표를 무효로 만들 수 있다.</li></ul><h3 id="인물-지윤재" tabindex="-1">인물 지윤재 <a class="header-anchor" href="#인물-지윤재" aria-label="Permalink to &quot;인물 지윤재&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 남관 제빙기 정비사</li><li>성격: 압축기 진동으로 제빙 주기를 읽고, 공구를 얼음 위에 두는 조수를 교대에서 뺀다. 말수는 적고 시운전 소음으로 대답한다.</li><li>개인 야망: 제빙기와 냉동 압축 주기를 공개 정비표로 묶어 전력이 흔들려도 하루치 얼음이 남게 한다.</li><li>공포: 한강 취수와 제빙 전력이 동시에 끊겨 얼음 원장이 종이쪼가리가 되는 것.</li><li>통치 방식: 교대마다 압축 온도와 벽돌 무게를 칠판에 쓰고, 상회 도장 없는 부품은 달지 않는다.</li><li>핵심 관계: 서나연의 벽돌 각인을 현장에서 받치는 사제이고, 나루희의 발전에 제빙 전력을 맞추며, 강민서의 밀봉 규격을 검수한다.</li><li>촉발 사건: 정전 첫날 제빙기가 멈추자 지윤재는 수동 사이클만 남기고 녹은 물로 중량을 맞추는 개조를 거부한다.</li><li>플레이어 개입: 수동 제빙 도구를 들여오거나, 도장 없는 개조의 발주자를 밝혀 정비사를 흔들 수 있다.</li></ul><h3 id="인물-마솔" tabindex="-1">인물 마솔 <a class="header-anchor" href="#인물-마솔" aria-label="Permalink to &quot;인물 마솔&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 냉동창고 물류상</li><li>성격: 손실을 숨기는 동료를 참지 못하고, 숫자보다 냄새로 창고 상태를 먼저 읽는다. 흥정에서는 웃지만 온도계가 흔들리면 표정이 굳는다.</li><li>개인 야망: 얼음 벽돌과 단기 식량 재고를 허가 원장으로 묶어 가락의 가격 주도권을 남관 현장에서 가져온다.</li><li>공포: 전력이 하루만 끊겨도 냉동 신용이 녹아내리는 것.</li><li>통치 방식: 재고 온도와 중량을 정오에 공개하고, 허위 재고가 나오면 해당 칸의 경매 자격을 박탈한다.</li><li>핵심 관계: 조민재의 삼호 창고 온도 기록을 현장에서 집행하는 계약이고, 송이든에게 냉동 화물을 맡기며, 주서람의 용산 칸 봉인과 인계 시각을 맞춘다.</li><li>촉발 사건: 정전으로 남관 삼호 창고의 온도가 위험선까지 오르자 마솔은 밤사이 옮기기 시작한 재고를 칸 단위로 봉한다.</li><li>플레이어 개입: 발전 부품을 구해 냉동을 살리거나, 녹은 재고를 가득 찬 것처럼 적은 장부를 폭로할 수 있다.</li></ul><h3 id="인물-연가온" tabindex="-1">인물 연가온 <a class="header-anchor" href="#인물-연가온" aria-label="Permalink to &quot;인물 연가온&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 남관시장 의무원</li><li>성격: 식중독 냄새를 상처보다 먼저 맡고, 경매 순서를 치료 순서로 바꾸라는 쪽지를 찢는다. 온화하나 얼음이 비면 시장 진료를 닫는다.</li><li>개인 야망: 호송 대원과 선창 노동자의 방역 주기를 상회정 부칙으로 올려 중립시장에도 의무 최저선을 남긴다.</li><li>공포: 상한 재고가 골목에 퍼진 뒤에야 약이 도착해, 의무소가 허위 재고의 면죄부가 되는 것.</li><li>통치 방식: 환자 명부와 시약 묶음을 동시에 게시하고, 녹은 얼음으로 열을 내린 상인은 진료 대기에서 뺀다.</li><li>핵심 관계: 서나연의 의무실 얼음 우선 배정을 침상에서 집행하고, 윤지율에게 시장 환자를 이송으로 넘기며, 류은비에게 약재를 빚진다.</li><li>촉발 사건: 정전 첫날 상인들이 녹은 물을 다시 얼렸다며 중량을 속이자 연가온은 시장 의무소를 봉쇄하고 허위 벽돌 접촉자를 격리한다.</li><li>플레이어 개입: 대체 시약을 호송해 봉쇄를 풀거나, 치료 순서를 경매표로 바꾼 쪽지를 폭로할 수 있다.</li></ul><h3 id="인물-나태경" tabindex="-1">인물 나태경 <a class="header-anchor" href="#인물-나태경" aria-label="Permalink to &quot;인물 나태경&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 시장 자경 순찰대 조장</li><li>성격: 부두 밧줄 소리로 무단 하역을 읽고, 호송 중 화물을 연 대원을 그날로 뺀다. 신의가 강하고 출발 직전까지 경로를 입 밖에 내지 않는다.</li><li>개인 야망: 남관 자경과 호송선단을 약소국 공동호송의 현장 뼈대로 키워 강국의 보호비를 시장 순찰로 대체한다.</li><li>공포: 호송 열차가 군수품을 실어 중립시장 정통성이 하루 만에 무너지는 것.</li><li>통치 방식: 경로와 무장은 출발 직전에만 알리고, 도착 중량이 출발과 다르면 전 대원 배급을 깎는다.</li><li>핵심 관계: 신태산의 호송 계약을 부두에서 집행하는 지휘를 받고, 설초아의 역 방송을 출항 시각과 맞추며, 장세화의 공동호송 초안을 현장 기준으로 검토한다.</li><li>촉발 사건: 한 호송칸에서 암사제 봉인 상자가 나오자 나태경은 선단 출항을 막고 전 칸을 재검색한다.</li><li>플레이어 개입: 밀수 상자의 출처를 밝히거나, 호송을 강행해 남관의 중립을 시험할 수 있다.</li></ul><h3 id="인물-양이든" tabindex="-1">인물 양이든 <a class="header-anchor" href="#인물-양이든" aria-label="Permalink to &quot;인물 양이든&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 경매 낙찰 전령</li><li>성격: 봉인 끈이 느슨하면 출발을 거부하고, 눈짓으로 낙찰을 바꾸는 입찰자를 잠재적 위조로 본다. 숨이 차도 사본 두 장을 한 손에 쥔다.</li><li>개인 야망: 물·전력·식량 계약의 낙찰 통지를 자신이 날인하는 전령 원장에만 유효하게 만들어 공통 결제권의 입이가 된다.</li><li>공포: 위조 낙찰 전갈 한 장이 빈 상자를 고가로 확정해 전령망이 직거래의 나팔이 되는 것.</li><li>통치 방식: 전갈을 경매판과 상회정에 동시에 보내고, 호송권 낙찰은 윤서하의 별도 봉투와 오해린의 연서가 둘 다 있어야 달린다.</li><li>핵심 관계: 윤서하의 호송권 비공개 경매를 봉인 상태로만 나르는 지휘이고, 마솔의 칸 자격 박탈을 배달하는 계약이며, 지온유의 후국 전갈과 낙찰 시점을 맞춘다.</li><li>촉발 사건: 흉작 소문만으로 빈 상자가 고가로 나가기 시작하자 양이든은 군량 낙찰 전갈을 재고 공개 전까지 가방에 잠근다.</li><li>플레이어 개입: 위조 전갈을 찾아 봉인을 지키거나, 가방 속 보류 문서를 폭로해 특정 후계자 몰아주기를 무력화할 수 있다.</li></ul><h3 id="인물-주나경" tabindex="-1">인물 주나경 <a class="header-anchor" href="#인물-주나경" aria-label="Permalink to &quot;인물 주나경&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 한강 취수 탐사원</li><li>성격: 취수구 수온으로 시간을 읽고, 지도에 없는 취수 우회를 자랑으로 여기지 않는다. 늦은 보고를 죄로 본다.</li><li>개인 야망: 노량진 취수와 제빙 원수를 한 장의 공개 해도로 그려 전력이 흔들려도 얼음 원장이 하루를 버티게 한다.</li><li>공포: 탐사 경로가 군사 비밀로 봉인되어 취수구가 수문 보호권의 잠금으로 팔리는 것.</li><li>통치 방식: 채수와 탁도를 같은 원장에 남기고, 붕괴 구간은 서나연과 오해린이 동시에 서명해야 표시한다.</li><li>핵심 관계: 서나연의 제빙 원수를 현장에서 측량하는 사제이고, 한재목의 수상 통행세를 꺼리며, 마길상의 교량 하부 채수와 우회 점선을 계약으로 나눈다.</li><li>촉발 사건: 정전 첫날 취수 펌프가 멈추자 주나경은 수동 우회 취수를 열고 중량 사기 원수의 유입을 차단한다.</li><li>플레이어 개입: 취수 호위를 맡아 우회를 성사시키거나, 비밀 잠금 표시를 폭로할 수 있다.</li></ul><h3 id="인물-차진아" tabindex="-1">인물 차진아 <a class="header-anchor" href="#인물-차진아" aria-label="Permalink to &quot;인물 차진아&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 결제권 원장 기록관</li><li>성격: 시간표의 빈칸을 사람보다 먼저 메우고, 구두 발행을 원장에 올리지 않는 선주를 위반자로 부른다. 숫자는 공개하되 해석은 난외에 남긴다.</li><li>개인 야망: 물·전력·식량 결제권을 자신이 감수한 원장에만 유효하게 해 오해린의 발행이 상회정의 공개 규칙이 되게 한다.</li><li>공포: 위조 표 한 장이 허위 재고로 발행되어 선주들이 한꺼번에 파산하는 것.</li><li>통치 방식: 발행 사본을 경매판과 상회정에 동시에 붙이고, 앞당긴 발행도 사흘 안의 재고 확인 없이는 무효라고 못 박는다.</li><li>핵심 관계: 오해린의 결제권 발행을 원장으로 옮기는 사제이고, 오도윤의 선주 표를 검증하며, 윤서린에게 발행 인준 사본을 넘길지 저울질한다.</li><li>촉발 사건: 부두 잔여 어획이 하루치로 줄자 차진아는 발행 앞당김을 원장에서 보류하고 허위 재고 표를 무효 난외에 적는다.</li><li>플레이어 개입: 재고 증인을 호송하거나, 난외 착복 노트를 폭로해 기록관을 교체하게 할 수 있다.</li></ul><h3 id="인물-설초아" tabindex="-1">인물 설초아 <a class="header-anchor" href="#인물-설초아" aria-label="Permalink to &quot;인물 설초아&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 노량진역 대합실 역장</li><li>성격: 승강장 습기로 경매 인파를 가늠하고, 호송 대기열을 군수 화차 뒤로 미루라는 명령을 모욕으로 듣는다. 온화하나 정전 예고가 뜨면 방송을 직접 잡는다.</li><li>개인 야망: 노량진 대합실을 경매·진료·호송이 한 지붕에서 서명되는 남부 허브로 만들어 중립시장의 대면 창구가 된다.</li><li>공포: 흉작 소문만으로 대합실이 봉쇄되고 상인이 부두 밀선으로 흩어지는 것.</li><li>통치 방식: 대합실 경매 대기표와 의무 창구를 매일 공개하고, 군수 화차는 호송선단이 떠난 뒤에만 승강장에 붙인다.</li><li>핵심 관계: 연가온의 의무소 봉쇄를 방송으로 알리는 동맹이고, 윤서하의 경매 순서를 승강장에서 집행하며, 신태산의 출항 시각을 칠판에 옮겨 적는다.</li><li>촉발 사건: 정전으로 냉동이 흔들리자 설초아는 대합실을 재고 공개 창구로 개방하고 군수 정차를 미룬다.</li><li>플레이어 개입: 대합실 봉쇄 명령을 막아 창구를 지키거나, 대기표 조작을 밝혀 역장을 강등시킬 수 있다.</li></ul><h3 id="인물-지마루" tabindex="-1">인물 지마루 <a class="header-anchor" href="#인물-지마루" aria-label="Permalink to &quot;인물 지마루&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 남관 냉동기지 감독</li><li>성격: 압축기 진동으로 과부하를 읽고, 시민 얼음보다 군량 충전에 칸을 내주라는 쪽지를 태운다. 과묵하고 교대 일지를 깎지 않는다.</li><li>개인 야망: 남관 냉동기지의 비상 전력을 제빙·식량 칸 전용으로 고정해 상회 신용의 심야 동맥이 된다.</li><li>공포: 한 번의 과방전으로 삼호 창고가 죽고, 그 정전을 수문 정부가 통행세로 압박하는 것.</li><li>통치 방식: 전력 배분을 공개 계기판에 남기고, 군수 충전은 벽돌 재고가 최저선을 넘을 때만 허용한다.</li><li>핵심 관계: 조민재의 온도 공개에 전력을 대는 지휘를 받고, 지윤재의 제빙 시운전에 출력을 맞추며, 한재목의 전력·물 계약을 기지 쪽에서 꺼린다.</li><li>촉발 사건: 정전으로 삼호 창고 온도가 위험선까지 오르자 지마루는 전력을 제빙기에 잠그고 외부 충전을 끊는다.</li><li>플레이어 개입: 대체 축전지를 구해 이중 공급을 열거나, 계기판 조작을 폭로해 감독을 교체할 수 있다.</li></ul><h3 id="인물-마하율" tabindex="-1">인물 마하율 <a class="header-anchor" href="#인물-마하율" aria-label="Permalink to &quot;인물 마하율&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 수산도매 시장 경매사</li><li>성격: 어획 시세를 강바람보다 빨리 읽고, 저울을 속이는 선주를 아침 추첨에서 즉시 뺀다. 흥정을 노래처럼 하지만 병든 아이 앞의 얼음 가격은 올리지 않는다.</li><li>개인 야망: 수산과 얼음 경매를 재고 공개와 함께만 열어 남관 시세가 공통 결제권의 공개 장부가 되게 한다.</li><li>공포: 가락의 가격 원장이 노량진 선석까지 삼켜 남부 식량이 동부 군량 시세로 팔리는 것.</li><li>통치 방식: 경매 시작 전 온도 표본 스티커를 확인하고, 녹은 재고는 낙찰이 되어도 출항시키지 않는다.</li><li>핵심 관계: 윤서하의 시작가를 수산에서 집행하는 계약이고, 마솔의 칸 자격과 순번을 나누며, 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.</li><li>촉발 사건: 흉작 소문만으로 빈 상자가 고가로 나가자 마하율은 군량 명목의 수산 경매를 거부하고 실재고만 낙찰한다.</li><li>플레이어 개입: 밀선 낙찰 장부를 폭로하거나, 온도 표본을 호송해 그의 공개 경매를 지킬 수 있다.</li></ul><h3 id="인물-연은재" tabindex="-1">인물 연은재 <a class="header-anchor" href="#인물-연은재" aria-label="Permalink to &quot;인물 연은재&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 남부 의료접근 이동의무차 반장</li><li>성격: 부두 수도꼭지가 마르면 진료 순서를 가족 단위로 바꾸고, 효율을 이유로 선주 칸만 건너뛰라는 말을 모욕으로 듣는다. 온화하나 약품 상자의 봉인 끈은 직접 묶는다.</li><li>개인 야망: 정전 골목에도 이동 의무차가 들어가게 해 중립시장의 의료 최저선을 상회정에 못 박는다.</li><li>공포: 상한 재고 환자가 난민 명부로만 남아 북산으로 떠밀리고 의무차가 호송 감옥이 되는 것.</li><li>통치 방식: 골목별 식중독 게시판을 운영하고, 정전 예고가 뜨면 서나연의 얼음 우선 배정 연서로 부두 옆 진료를 연다.</li><li>핵심 관계: 연가온의 시장 진료가 봉쇄되면 환자를 골목으로 받고, 장세화의 의료호송을 남관에서 피하지 않으려 빚을 지며, 백온의 가족 명부와 이동 진료 명단을 교환한다.</li><li>촉발 사건: 정전으로 식량이 상하기 시작하자 연은재는 이동 의무차만으로 부두 진료를 열고 군량 수색을 거부한다.</li><li>플레이어 개입: 시약 상자를 호송해 부두 진료를 유지하거나, 명부 양도 밀약을 찾아 반장을 위태롭게 할 수 있다.</li></ul><h3 id="인물-나루희" tabindex="-1">인물 나루희 <a class="header-anchor" href="#인물-나루희" aria-label="Permalink to &quot;인물 나루희&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 남관 제빙 비상발전 운전장</li><li>성격: 연료 냄새에 예민하고 구두 배전을 싫어한다. 제빙기보다 경매 조명에 전력을 돌리라는 정치적 압박을 모욕으로 여긴다.</li><li>개인 야망: 남관 비상 발전과 제빙 전력을 하나의 공개 배전망으로 묶어 얼음 원장의 품질 주권을 지킨다.</li><li>공포: 연료가 바닥난 밤에 냉동이 녹고, 그 공백을 수문 보호권이 메우는 것.</li><li>통치 방식: 매 교대 연료 잔량과 출력 일지를 봉인해 지마루에게 보내고, 최저 출력 이하면 대표의 독촉이 있어도 경매 배전을 끊는다.</li><li>핵심 관계: 지마루의 냉동기지 전력 배분을 발전 쪽에서 받치고, 지윤재의 시운전에 출력을 맞추며, 오해린의 재고 공개에는 복종하되 은폐 배전은 거부한다.</li><li>촉발 사건: 정전과 제빙기 정지가 겹치자 나루희는 비상 발전을 제빙과 삼호 창고에 잠그고 경매 조명을 끈다.</li><li>플레이어 개입: 대체 연료를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다.</li></ul><h3 id="인물-섭다은" tabindex="-1">인물 섭다은 <a class="header-anchor" href="#인물-섭다은" aria-label="Permalink to &quot;인물 섭다은&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 냉동고 사고 증인</li><li>성격: 녹은 재고의 냄새를 숫자보다 먼저 맡고, 온도계가 흔들린 밤을 사고에서 빼자는 동료를 경멸한다. 흥정에서는 웃지 않는다.</li><li>개인 야망: 탁수 여름의 냉동 사고를 상회정 공개 원장에 묶어 허위 재고가 결제권의 담보가 되지 않게 한다.</li><li>공포: 증언이 지연 공개 쪽으로 잘려 자신이 은폐의 시장 들러리가 되는 것.</li><li>통치 방식: 사고 당일 온도와 중량을 정오에 다시 읽고, 칸을 옮긴 손은 이름과 시각을 같이 적게 한다.</li><li>핵심 관계: 오해린의 재고 공개에 증언을 보태고, 조민재의 삼호 창고 온도 기록을 현장에서 받치며, 평서아가 삼킨 가짜 약의 보관 칸을 같은 사고로 가리킨다.</li><li>촉발 사건: 여름의 탁수와 가짜 약으로 노량진 냉동재고가 위기에 빠지자 섭다은은 위험선까지 오른 칸을 잠그고 야간 이전을 증언했다.</li><li>플레이어 개입: 증인을 상회정까지 호송하거나, 녹은 재고를 가득 찬 것처럼 적은 장부를 폭로할 수 있다.</li></ul><h3 id="인물-평서아" tabindex="-1">인물 평서아 <a class="header-anchor" href="#인물-평서아" aria-label="Permalink to &quot;인물 평서아&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 가짜 약품 경매 피해자</li><li>성격: 낙찰 봉투를 열기 전에 약 냄새를 맡고, 봉인만 번지르르한 상자를 고가에 받은 아침을 잊지 못한다. 목소리가 갈라져도 시작가는 다시 묻는다.</li><li>개인 야망: 가짜 약이 섞인 낙찰을 무효로 돌려 남관 경매가 의료 신뢰의 하청 시장이 되지 않게 한다.</li><li>공포: 피해 진술이 시세 안정 명분으로 묻혀 다음 회로 같은 상자가 나가는 것.</li><li>통치 방식: 낙찰 사본과 투약 사고를 같은 벽에 붙이고, 봉인 출처가 없는 약은 재경매에 올리지 못하게 막는다.</li><li>핵심 관계: 연가온의 시장 의무소에서 피해를 기록하고, 류은비에게 약효 검증을 청구하며, 오해린의 공통 결제권이 가짜 약 대금까지 삼키지 않기를 요구한다.</li><li>촉발 사건: 여름의 탁수와 가짜 약이 유통되자 평서아는 남관 경매판에서 산 상자 하나를 깨 보이고 낙찰 무효를 외쳤다.</li><li>플레이어 개입: 깨진 표본을 마곡까지 호송하거나, 시세 안정 명분의 은폐 쪽지를 폭로할 수 있다.</li></ul><h3 id="인물-단노을" tabindex="-1">인물 단노을 <a class="header-anchor" href="#인물-단노을" aria-label="Permalink to &quot;인물 단노을&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 탁수 재고 야간 이전 목격자</li><li>성격: 부두 밧줄 소리로 무단 하역을 읽고, 밤사이에 칸을 옮기는 발소리를 재고 공개보다 정직하다고 본다. 신의가 강해 본 시각을 줄이지 않는다.</li><li>개인 야망: 탁수 직후 야간 이전의 경로를 공개 목격으로 남겨 얼음 원장이 종이쪼가리가 되기 전에 손을 가리키게 한다.</li><li>공포: 목격이 호송권 비공개 경매의 흥정 재료가 되는 것.</li><li>통치 방식: 이전 시각과 도착 중량을 자경 일지에 적고, 출발과 다른 무게는 전 칸 재검색의 근거로 삼는다.</li><li>핵심 관계: 서나연의 벽돌 각인이 밤에 바뀐 칸을 가리키고, 마솔의 칸 봉쇄를 목격으로 받치며, 지마루의 냉동기지 전력 배분이 끊긴 시각을 같은 줄에 둔다.</li><li>촉발 사건: 여름의 탁수와 가짜 약 직후 상인들이 재고를 밤사이에 옮기자 단노을은 부두 그늘에서 칸 번호를 모두 적었다.</li><li>플레이어 개입: 일지를 경매 전에 공개하거나, 목격자를 침묵시키려는 호송권 거래를 막을 수 있다.</li></ul><h3 id="인물-순재민" tabindex="-1">인물 순재민 <a class="header-anchor" href="#인물-순재민" aria-label="Permalink to &quot;인물 순재민&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 호송칸 봉인 상자 증인</li><li>성격: 호송 중 화물을 연 대원을 그날로 빼고, 암사 문장이 찍힌 상자를 중립의 적으로 부른다. 과묵하나 도착 중량이 다르면 선단을 세운다.</li><li>개인 야망: 남관 호송칸의 밀수 봉인을 공동호송의 공개 죄목으로 올려 시장 자경이 보호비의 하청이 되지 않게 한다.</li><li>공포: 증언 뒤에 선단이 군수품을 실은 채로 출항해 중립시장 정통성이 하루 만에 무너지는 것.</li><li>통치 방식: 경로와 무장은 출발 직전에만 확인하고, 봉인 상자가 나오면 전 칸을 다시 열어 중량을 맞춘다.</li><li>핵심 관계: 신태산의 호송 반에서 상자를 증언하고, 나태경의 출항 저지를 현장에서 받치며, 배우진의 무기 칸이 시장 선단에 섞였는지 따진다.</li><li>촉발 사건: 겨울의 검은 배차표와 같은 봉인 상자가 남관 호송칸에서 나오자 순재민은 출항 밧줄을 끊고 증인석에 섰다.</li><li>플레이어 개입: 밀수 상자의 출처를 밝히거나, 호송을 강행해 증인의 중립을 시험할 수 있다.</li></ul><h3 id="인물-홍지훈" tabindex="-1">인물 홍지훈 <a class="header-anchor" href="#인물-홍지훈" aria-label="Permalink to &quot;인물 홍지훈&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 급수 시세 폭등 상인</li><li>성격: 물값이 뛰는 아침의 빈 상자를 흉작 소문보다 먼저 읽고, 눈짓으로 낙찰을 바꾸는 입찰자를 자리에서 뺀다. 계산은 빠르고 잔인할 만큼 공정하다.</li><li>개인 야망: 개막 물가 폭등을 공개 시세로만 교환하게 만들어 강국의 비공개 직거래가 남관 경매판을 빈 의자로 만들지 못하게 한다.</li><li>공포: 자신이 올린 시작가가 군량 입찰의 신호등처럼 읽히는 것.</li><li>통치 방식: 시작가와 낙찰가를 벽에 쓰고, 실재고 없는 물은 다음 회로 미룬다.</li><li>핵심 관계: 윤서하의 경매 규칙을 물가 품목에서 집행하고, 오해린의 결제권 발행 속도를 시세로 견제하며, 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.</li><li>촉발 사건: 개막일 세 번째 급수계약 만료로 물 가격이 오르자 홍지훈은 빈 상자의 고가 낙찰을 멈추고 실재고만 남겼다.</li><li>플레이어 개입: 실제 재고를 경매 전에 공개하거나, 특정 후계자에게 군량 입찰을 몰아주려는 쪽지를 찢을 수 있다.</li></ul><h3 id="인물-추보람" tabindex="-1">인물 추보람 <a class="header-anchor" href="#인물-추보람" aria-label="Permalink to &quot;인물 추보람&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 약소국 회의 식량 호송 선주</li><li>성격: 출항 전 연료와 얼음 잔량을 숨기는 선주를 파산보다 먼저 멈추고, 표를 물건처럼 옮기는 버릇은 회의 호송에서만 접는다. 손실을 나중으로 미루는 사람을 경멸한다.</li><li>개인 야망: 열한 자리 회의의 식량 호송을 선주 지분이 아니라 상호호송 조약의 실무로 묶어 남관이 분할 복속의 부두가 되지 않게 한다.</li><li>공포: 외부 어획이 끊긴 채로 허위 재고 표가 회의 칸을 채워 선단이 한꺼번에 가라앉는 것.</li><li>통치 방식: 출항 잔량을 공개하고, 미상환 표가 쌓인 선주의 회의 부두 사용을 정지한다.</li><li>핵심 관계: 오도윤의 상회정 표를 회의 호송에서 거르고, 정유라의 공동교섭 사절에 식량 칸을 붙이며, 장세화의 상호호송 초안을 선석에서 검토한다.</li><li>촉발 사건: 둘째 해 봄 열한 자리 회의가 열리자 추보람은 강국 군량 명목의 선석을 거부하고 약소국 식량 칸만 띄웠다.</li><li>플레이어 개입: 선주 표를 모아 호송을 통과시키거나, 허위 재고로 산 표를 무효로 만들 수 있다.</li></ul><h3 id="인물-어도윤" tabindex="-1">인물 어도윤 <a class="header-anchor" href="#인물-어도윤" aria-label="Permalink to &quot;인물 어도윤&quot;">​</a></h3><ul><li>소속: 노량진남관상회</li><li>직위: 첫 급수협약 시장 증인</li><li>성격: 물과 부품이 서로 다른 권역에 흩어지던 첫해를 저울처럼 기억하고, 임시 협약을 영원한 권리라고 부르는 젊은 상인을 고쳐 준다. 말수는 적고 날짜는 정확하다.</li><li>개인 야망: 첫 급수협약을 공공권리로 본 증언을 남관 원장에 남겨 보호계약으로만 읽는 손이 시세를 독점하지 못하게 한다.</li><li>공포: 자신의 기억이 수문동맹의 선전 문구로 잘려 시장이 보호국의 창구가 되는 것.</li><li>통치 방식: 협약 당시 교환 품목과 무게를 벽에 다시 쓰고, 후일 해석은 당시 증인 두 명의 재서명만 받는다.</li><li>핵심 관계: 오해린의 중립시장 정통성에 첫해 증언을 보태고, 한재목의 물 교환을 시세로 기억하며, 임하준이 건넨 펌프 부품 상자의 무게를 아직도 손에 남긴다.</li><li>촉발 사건: 붕괴 1년 첫 급수협약이 맺어질 때 어도윤은 노량진 선석에서 물과 부품이 바뀌는 장면을 증인으로 보았다.</li><li>플레이어 개입: 잘린 기억 문구를 되찾거나, 공공권리 해석의 증인을 호송할 수 있다.</li></ul>',50)])])}const q=i(t,[["render",h]]);export{b as __pageData,q as default};
